function render(s,project){let list=(s.purchases||[]).filter(p=>project==='all'||p.project===project);return '<section class="page-head"><div><h1>Compras e notas</h1><p class="subtitle">Uma compra ou nota reúne vários itens. Só a confirmação gera contas a pagar.</p></div><div class="actions"><button class="button primary" data-action="purchase-new">+ Compra / nota em planilha</button><button class="button secondary" data-action="purchase-import">Importar XML NF-e</button></div></section><p class="section-note">PDF: anexe o documento e preencha ou cole os itens na grade. A extração automática será ajustada a partir de um PDF de exemplo.</p><div class="table-wrap"><table><thead><tr><th>Documento / fornecedor</th><th>Obra</th><th>Emissão</th><th>Itens</th><th>Total</th><th>Situação</th><th>Ações</th></tr></thead><tbody>'+list.map(p=>'<tr><td>'+h(p.kind)+' '+h(p.number)+'<br>'+h(p.supplier)+'</td><td>'+h(s.projects.find(x=>x.id===p.project)?.name)+'</td><td>'+h(p.date)+'</td><td>'+p.items.length+'</td><td>'+h(money(p.total??totals(p)))+'</td><td>'+h(p.status)+'</td><td><button class="text-btn" data-action="purchase-view:'+h(p.id)+'">Visualizar</button> <button class="text-btn" data-action="purchase-edit:'+h(p.id)+'">Editar</button> <button class="text-btn red-text" data-action="purchase-remove:'+h(p.id)+'">Excluir</button></td></tr>').join('')+'</tbody></table></div>'+(list.length?'':'<p class="empty">Cadastre a primeira compra ou importe uma NF-e.</p>')}
